style.css:
@-moz-document domain("youtube.com") {
/* Change YouTube Logo to a Cookie */
  #logo-icon {
    background-image: url("https://cdn-icons-png.flaticon.com/512/1046/1046784.png");
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    width: 100% !important;
    height: 100% !important;
  }

  #logo-icon svg {
    display: none !important;
  }

  /* Set Cookie Background */
  body {
    background-image: url("https://i.imgur.com/B5R5KfJ.jpg");
    background-size: cover;
    background-repeat: repeat;
  }

  /* Make content boxes a bit see-through so the cookies show */
  ytd-app, ytd-page-manager, ytd-browse, #page-manager {
    background-color: rgba(255, 255, 255, 0.8) !important;
  }
}
